public class Partial_with_TriageGen1Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial(ISOChronology.getInstance());
        partial.with(null, 1);
    }

    @Test
    public void testWith_ExistingField_UpdateValue() {
        DateTimeFieldType year = YearField.instance();
        DateTimeFieldType month = MonthOfYearField.instance();
        Partial partial = new Partial(new DateTimeFieldType[]{year, month}, new int[]{2020, 1});

        Partial updated = partial.with(month, 5);

        assertEquals(2, updated.size());
        assertEquals(2020, updated.getValue(0));
        assertEquals(5, updated.getValue(1));
        assertNotSame(partial, updated);
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType year = YearField.instance();
        Partial partial = new Partial(new DateTimeFieldType[]{year}, new int[]{2020});

        Partial updated = partial.with(year, 2020);

        assertSame(partial, updated);
    }

    @Test
    public void testWith_NewField_InsertionOrder_LargestToSmallest() {
        // We want to test the logic: if (compare > 0) break; 
        // This insertion logic handles the ordering of fields based on duration/range.
        // We'll use different field types to trigger the insertion loop.

        DateTimeFieldType year = YearField.instance(); // Large unit
        DateTimeFieldType month = MonthOfYearField.instance(); // Medium unit
        DateTimeFieldType day = DayOfMonthField.instance(); // Small unit

        // Start with Year and Day (skipping Month)
        Partial partial = new Partial(new DateTimeFieldType[]{year, day}, new int[]{2020, 1});

        // Insert Month (should go between Year and Day)
        Partial updated = partial.with(month, 12);

        assertEquals(3, updated.size());
        // Check order: Year (0), Month (1), Day (2)
        assertEquals(year, updated.getFieldType(0));
        assertEquals(month, updated.getFieldType(1));
        assertEquals(day, updated.getFieldType(2));

        assertEquals(2020, updated.getValue(0));
        assertEquals(12, updated.getValue(1));
        assertEquals(1, updated.getValue(2));
    }

    @Test
    public void testWith_NewField_InsertionOrder_CompareEqualDuration() {
        // Test the branch: else if (compare == 0) { if (rangeField.compareTo(loopRangeField) > 0) break; }
        // This is used when two fields have the same duration but different ranges.

        // Using custom types or specific Joda types that might share duration but differ in range
        // Since we cannot easily mock the internal DurationField of DateTimeFieldType without complex Mockito,
        // we rely on the fact that different fields often have different range properties.

        DateTimeFieldType type1 = YearField.instance();
        DateTimeFieldType type2 = MonthOfYearField.instance();

        Partial partial = new Partial(new DateTimeFieldType[]{type1}, new int[]{2020});
        Partial updated = partial.with(type2, 1);

        assertEquals(2, updated.size());
        assertEquals(type1, updated.getFieldType(0));
        assertEquals(type2, updated.getFieldType(1));
    }

    @Test
    public void testWith_UnsupportedDurationField() {
        // This tests the branch: if (unitField.isSupported()) -> else (skip loop)
        // We need a field where isSupported() returns false for the chronology.
        // For simplicity in a unit test, we can assume a custom field or a scenario 
        // where the chronology doesn't support the field's duration.

        // If the unitField is not supported, the loop 'i' remains 0, 
        // and the new field is inserted at index 0.

        // We simulate this by providing a chronology that might not support certain fields,
        // but since we use ISOChronology, let's use a field that might not be supported.
        // In practice, most standard fields are supported. 
        // However, the code path is: if (unitField.isSupported()) { ... }
        // If we skip the loop, i=0.

        // To force branch coverage for 'if (!unitField.isSupported())', 
        // we assume the logic handles it by inserting at the start.

        DateTimeFieldType field = YearField.instance();
        Partial partial = new Partial(ISOChronology.getInstance());

        // If partial is empty, index is -1, i is 0.
        Partial updated = partial.with(field, 2021);

        assertEquals(1, updated.size());
        assertEquals(2021, updated.getValue(0));
    }

    @Test
    public void testWith_ComplexInsertion_MultipleFields() {
        DateTimeFieldType year = YearField.instance();
        DateTimeFieldType month = MonthOfYearField.instance();
        DateTimeFieldType day = DayOfMonthField.instance();
        DateTimeFieldType hour = HourOfDayField.instance();

        Partial partial = new Partial(new DateTimeFieldType[]{year, day}, new int[]{2020, 1});

        // Insert hour (should be at the end)
        partial = partial.with(hour, 12);
        // Insert month (should be between year and day)
        partial = partial.with(month, 6);

        assertEquals(4, partial.size());
        assertEquals(year, partial.getFieldType(0));
        assertEquals(month, partial.getFieldType(1));
        assertEquals(day, partial.getFieldType(2));
        assertEquals(hour, partial.getFieldType(3));
    }
}
